import itertools


class EventBus:
    def __init__(self):
        self._subscribers = {}              # topic -> {subscription id: function}, in subscription order
        self._ids = itertools.count()

    def subscribe(self, topic, fn):
        subscription = next(self._ids)      # every subscription has its own id, even for the same function
        self._subscribers.setdefault(topic, {})[subscription] = fn

        def unsubscribe():
            self._subscribers.get(topic, {}).pop(subscription, None)   # harmless the second time

        return unsubscribe

    def publish(self, topic, payload):
        errors = []
        # iterate over a copy: a subscriber may subscribe or unsubscribe while it runs
        for fn in list(self._subscribers.get(topic, {}).values()):
            try:
                fn(payload)
            except Exception as error:
                errors.append(error)
        return errors
